namespace Plugin.AncientCivilization
{
    public sealed class AncientMission
    {
        public readonly int Id,Floor,Kind;public readonly string Title,Speaker,Brief,Reply,Clue,Result;public readonly string[] Tasks;
        public AncientMission(int id,int kind,string title,string speaker,string brief,string reply,string clue,string result,string[] tasks)
        {Id=id;Floor=id/4;Kind=kind;Title=title;Speaker=speaker;Brief=brief;Reply=reply;Clue=clue;Result=result;Tasks=tasks;}
    }
    public sealed class AncientCitizen
    {
        public readonly int Id,Floor,Role;public readonly float X,Y;public readonly string Name;public readonly string[] Before,After;
        public AncientCitizen(int id,int floor,float x,float y,string name,int role,string[] before,string[] after)
        {Id=id;Floor=floor;X=AncientCampaignData.ResidentX(id,floor,x);Y=id<3?y:0;Name=name;Role=role;Before=before;After=after;}
    }
    public static class AncientCampaignData
    {
        public const string HeroName="백명";
        // The opening residents stay on the original patrol street. Later residents
        // are encountered along the same road as the chapter, including its rest bridges.
        public static float ResidentX(int id,int floor,float openingX)
        {
            if(floor==0)return id<3?openingX:id==3?108:AncientChapterLayout.CaseRight(2)+24;
            int first=floor*4,slot=id%5;
            if(slot==0)return AncientChapterLayout.FloorStart(floor)+24;
            if(id==24)return AncientChapterLayout.CaseLeft(19)+10;
            if(slot==1)return AncientChapterLayout.CaseRight(first)+24;
            if(slot==2)return AncientChapterLayout.CaseRight(first+1)+24;
            if(slot==3)return AncientChapterLayout.CaseRight(first+2)+(floor==4?-24:24);
            return AncientChapterLayout.CaseEnd(floor)+64;
        }
        public static readonly AncientMission[] Missions={
            new AncientMission(0,0,"사라진 야간 배정","야간 작업반장","코어 절도는 끝났는데 생산소 계량기는 아직 비어 있습니다. 야간 출고가 따로 있었어요.","도난량과 야간 출고량을 따로 확인하겠습니다.","일반 출고와 C-00 예비분은 서로 다른 계량기를 쓴다.","도난 이전에도 코어가 빠져나갔습니다. 절도 사건 하나로 설명되지 않는군요.",new string[]{"작업반 증언","야간 계량기","출고 전표"}),
            new AncientMission(1,3,"끊어진 작업장","정비사 한석","압력 배전함이 봉인됐어요. 작업반이 안에 남았는데 원격 복구도 차단됐습니다.","파손부를 잘라내고 입자를 모아 수동으로 전력을 넣겠습니다.","비상 전력은 주민용이지만 봉인 명령은 최상층 직할이다.","비상선을 복구했습니다. 주민 전력을 누가 먼저 끊었는지 기록해 두겠습니다.",new string[]{"파손 절연판 베기","복구 회로 확인","수광부에 입자 레이저"}),
            new AncientMission(2,2,"마지막 작업자","야간 작업자 재하","다들 피난 갔다고 써 있겠죠. 전 문이 잠겨 못 나갔어요.","문부터 열겠습니다. 증언은 안전한 곳에서 듣죠.","피난 확인서가 실제 퇴거보다 먼저 작성됐다.","확인서는 미리 만들어졌습니다. 이건 현장 혼선이 아니라 절차의 문제입니다.",new string[]{"봉인 장치 베기","작업자와 대화","출구까지 작업자 보호"}),
            new AncientMission(3,0,"사본을 남기는 이유","통신관","회수품 이송 승인이 바뀌었다. 지워지기 전에 생산소의 로컬 기록을 챙겨라.","정식 인계는 하되 사본은 남기겠습니다.","별도 이송 승인 시간과 용의자 검거 시간의 순서가 맞지 않는다.","검거 전에 이미 별도 이송이 승인됐습니다. 윗층에 가서 수령 기록을 확인하겠습니다.",new string[]{"로컬 인계표","승인 시각","사본 송신"}),
            new AncientMission(4,3,"불 꺼진 진료소","간호사 윤서","수술실 대신 대기실 불부터 껐어요. 그래도 코어가 모자라요.","당장 쓸 전력부터 돌리고 배정표를 확인하겠습니다.","진료소는 절도 사흘 전부터 정상 배정분을 받지 못했다.","도둑이 가져간 코어만 부족한 게 아닙니다. 그전 물량의 행방을 찾아야 합니다.",new string[]{"탄 절연판 베기","진료소 배선 기록","비상 수광부 레이저"}),
            new AncientMission(5,2,"돌아오지 않은 배달","배달원 소라","그 기술자가 우리 주소를 적었어요. 훔친 코어를 여기 보내려던 거예요.","그 사람이 왜 그런 선택을 했는지 끝까지 확인하겠습니다.","용의자는 진료소 반환 신청을 거절당한 운송 기술자였다.","주민을 돕겠다는 이유로 다른 주민을 위험하게 했군요. 동기를 확인해도 범행이 없어지는 건 아닙니다.",new string[]{"물류 봉쇄판 베기","배달원 증언","진료소 경계까지 보호"}),
            new AncientMission(6,1,"포인트를 파는 골목","급식소 연희","포인트를 사면 배급 줄이 짧아진대요. 코어가 부족한 게 돈벌이가 됐어요.","중개 설비와 거래 흔적을 확보하겠습니다. 주민 명단은 보호하죠.","밀매 조직은 부족한 물량을 이용했지만 실제 회수 승인자는 아니다.","조직의 장부에는 중층 승인번호가 있습니다. 조직만 잡아서는 전력이 돌아오지 않습니다.",new string[]{"위조 심사기 베기","불법 중계기 베기","장부 봉인판 베기"}),
            new AncientMission(7,0,"빈 수령처의 장부","배급 담당 미루","누가 받았는지 모르면 도난으로 처리하래요. 우리가 못 받았어도요.","수령처가 지워지기 전 번호를 찾겠습니다.","지역 경비장이 보관한 원장에 행정구 수정 이력이 남아 있다.","이 원장은 경비장에게서 확보해야 합니다. 절도범 숫자로 물량을 맞추는 수사는 끝내죠.",new string[]{"미수령 명단","수정 이력","원장 보관처"}),
            new AncientMission(8,0,"접수되지 않은 사건","기록원 다인","사건번호는 있는데 신고가 없어요. 반대로 신고는 있는데 사건번호가 없는 사람도 있고요.","누락을 실수가 아니라 증거로 접수하겠습니다.","행정 기관은 실종과 코어 미수령을 별개의 민원으로 분리했다.","같은 시각의 같은 차량이 두 신고에 등장합니다. 한 사건으로 묶겠습니다.",new string[]{"주민 신고 원본","차량 시각표","사건 묶음 접수"}),
            new AncientMission(9,1,"닫힌 보관소","시설 관리원 규식","감사 알림이 뜨자 원본 보관소부터 잠겼어요. 폐기 장치도 돌아갑니다.","기록을 지우는 회선부터 끊겠습니다.","폐기 명령은 원본 열람 신청 직후 C-00으로 갱신됐다.","기록은 보존했습니다. 열람하려고 했다는 이유로 누가 폐기부터 명령했는지 남기죠.",new string[]{"폐기 전원판 베기","보관소 잠금판 베기","원본 봉인판 베기"}),
            new AncientMission(10,0,"수령처를 지운 손","통신관","내 사본에는 수령처가 남아 있다. 네 원본과 수정 시간을 대조하자.","원본을 신뢰하라는 규정부터 확인해야겠군요.","수령처 삭제는 현장 입력이 아니라 상층 일괄 수정이다.","원본이 나중에 바뀌었습니다. 사본을 남긴 사람이 규정 위반자가 되는 구조였군요.",new string[]{"원본 복구본","사본 대조 단말","수정 서명"}),
            new AncientMission(11,2,"조사 대상의 이름","접수 직원 주안","당신 이름이 조사관 칸에서 피조사자 칸으로 옮겨졌어요. 저도 곧 그렇게 될 겁니다.","기록을 지킨 사람을 혼자 남겨 두지는 않겠습니다.","C-00을 조회한 직원과 경찰에게 심사 보류가 걸린다.","기록 집행관이 길을 막고 있습니다. 당신은 안전 통로로 가세요. 원본은 제가 지키겠습니다.",new string[]{"보안 봉인판 베기","직원과 대화","직원 안전 통로 확보"}),
            new AncientMission(12,3,"밝은 거리의 정전","거주구 설비사 지완","여긴 불이 켜져 있으니 아무도 아래가 꺼진 걸 몰라요. 공용 전력이 따로 빠집니다.","장식등이 아니라 빠져나가는 선을 따라가겠습니다.","주거 전력과 회수 작전 전력이 한 설비에서 갈라진다.","상층 주민에게 모두 배급된 게 아닙니다. 회수 작전용 선로를 찾았습니다.",new string[]{"차단 덮개 베기","분기 도면","계측 수광부 레이저"}),
            new AncientMission(13,0,"계약서 밖의 사람들","계약 담당 은재","계약서는 설비 재배치인데 첨부는 주민 명단이에요. 서명하면 전 사람을 옮긴 게 됩니다.","계약서와 명단을 같은 증거로 남기겠습니다.","재배치 대상은 사고 지역이 아니라 회수 작전의 하부 지반이다.","안전 점검을 핑계로 길을 비우고 있군요. 명단에 있는 사람들에게 알려야 합니다.",new string[]{"재배치 계약","주민 명단","지반 도면"}),
            new AncientMission(14,2,"명단 속 주소","이송 예정자 해솔","우리 집은 아래층이에요. 여기에선 주소도 심사 대상이래요.","주소 때문에 위험해진 사람을 포인트로 가를 수는 없습니다.","이송 명단에 있는 코어 번호가 하층 배정 번호와 같다.","명단과 코어가 같은 목적지로 갑니다. 통신관에게 주민 대피를 요청하겠습니다.",new string[]{"검문 잠금판 베기","이송 예정자 증언","거주구 안전 경계까지 보호"}),
            new AncientMission(15,0,"보류된 승진","통신관","추가 점수는 승인됐지만 이동 심사가 멈췄다. 이유가 비어 있어.","제가 지킨 기록 때문에 제가 기록에서 막히는군요.","최상층 출입은 포인트가 아니라 직할 승인으로 통제된다.","코어 보안 병기가 외벽 통로를 막았습니다. 정문이 닫혔다면 기록을 버리는 대신 돌아가겠습니다.",new string[]{"포인트 심사서","직할 승인 규정","외벽 정비 경로"}),
            new AncientMission(16,1,"이름 없는 정비로","정비 노동자 노을","정문 기록이 없으면 여기선 존재하지 않는 사람이에요. 안쪽 검문 장치만 피하세요.","주민이 없는 곳에서 봉쇄 설비만 끊겠습니다.","정식 출입 기록 밖으로 나간 사람은 포인트 심사에서도 사라진다.","봉쇄를 해제했습니다. 사라진 기록이 곧 사라진 사람을 뜻하는 건 아닙니다.",new string[]{"외벽 감시판 베기","검문 전송판 베기","잠입 경계판 베기"}),
            new AncientMission(17,0,"삭제된 이의 신청","야간 관제원 여울","이의 신청은 기각되는 게 아니에요. 접수되기 전에 지워져요.","누가 신청했는지 말하지 않아도 됩니다. 지워진 시각만 보겠습니다.","포인트가 동결된 사람들의 신청이 같은 승인선에서 지워졌다.","저와 같은 방식으로 길이 막힌 사람들이 있습니다. 그중 누군가는 아직 이 안에 있겠군요.",new string[]{"접수 대기열","삭제 시각","승인선 경로"}),
            new AncientMission(18,0,"누구도 승인하지 않은 길","통신관","네 위치가 관제에서 끊긴다. 돌아오라는 명령만 계속 내려온다.","돌아가면 이 기록도 사라집니다. 앞으로 이어지는 길을 보내 주세요.","회장실로 가는 통로에 신원 미상의 사격 흔적이 남아 있다.","회장실 전방에 누군가 있습니다. 목적을 알기 전에는 동료도 적도 단정하지 않겠습니다.",new string[]{"사격 흔적 조사","우회 경로 확인","회장실 통로 표식"}),
            new AncientMission(19,0,"비어 있는 회장실","보관실 관리인 유담","회장은 집무실에 없어요. 작전 날이면 개인 노트와 실행 계획을 따로 둡니다.","기록과 계획을 대조하겠습니다. 그다음은 창밖의 움직임을 보죠.","매몰 문명 연구와 오늘의 코어 회수 계획이 같은 승인번호를 쓴다.","회수 계획은 오늘 실행됩니다. 책상에 남은 노트를 직접 확인해야 합니다.",new string[]{"연구 노트 색인","회수 작전 승인서","출발 시각 기록"})
        };
        public static readonly AncientCitizen[] Citizens={
            new AncientCitizen(0,0,12f,0f,"정비사 한석",0,new string[]{"팔의 도관은 손대지 않았어요. 바깥 판만 갈았습니다. 손가락도 없는 장비를 손처럼 쓰시네요.","밤에 검문 안내가 떴어요. 조커라는 항목인데, 이름인지 물건인지 설명이 없더군요."},new string[]{"배정이 돌아오면 야간 작업도 줄겠죠. 경위님 포인트보다 그게 먼저예요."}),
            new AncientCitizen(1,0,29f,0f,"급식소 연희",1,new string[]{"위로 올라간 사람도 밥은 먹어요. 다만 밥이 어디서 오는지 안 내려다보죠.","아침 순찰이면 남은 수프라도 가져가요."},new string[]{"사람이 사라진 자리엔 식권이 남아요. 그걸 도난 처리하면 사람도 도둑이 되나요?"}),
            new AncientCitizen(2,0,73f,0f,"주민 민서",2,new string[]{"천장은 왜 하늘색이 아니에요? 엄마는 위로 가면 진짜 빛이 있대요.","전 엄마랑 같이 가면 돼요. 혼자 올라가는 건 싫어요."},new string[]{"오늘은 문을 안 잠가도 돼요? 그럼 저녁에 엄마가 돌아올 수 있겠네요."}),
            new AncientCitizen(3,0,91f,0f,"순찰소장",3,new string[]{"백 경위, 검거 숫자보다 사람이 무사한지 먼저 확인해라.","누가 네 점수를 올려 줘도 현장 기록은 네가 써야 한다."},new string[]{"내가 승인할 수 있는 건 여기까지다. 네 기록까지 대신 써 줄 수는 없어."}),
            new AncientCitizen(4,0,54f,1f,"생산소 작업반장",0,new string[]{"우린 위에서 쓸 코어도 만들어요. 아래에서 만드는 게 아래 것이라는 뜻은 아니래요.","그럼 아래 주민의 전력은 누가 책임지는 걸까요."},new string[]{"야간 출고 장부 사본은 남겨 뒀어요. 현장에 남은 건 사람이니 사람 말을 들어 주세요."}),
            new AncientCitizen(5,1,139f,0f,"간호사 윤서",1,new string[]{"배급표가 아니라 환자를 보고 불을 끄고 있어요. 꺼도 되는 방을 고르는 일부터 잘못됐죠.","코어를 돌려 달라는 신청서는 세 번 냈습니다. 답변은 같은 양식이었어요."},new string[]{"전력은 돌아왔지만 환자들이 다 돌아온 건 아니에요. 코어 숫자와 사람 숫자를 따로 세 주세요."}),
            new AncientCitizen(6,1,185f,0f,"배달원 소라",2,new string[]{"그 기술자, 돈부터 물어보지 않았어요. 주소가 맞는지부터 확인했죠.","그렇다고 추격 중 물체를 던진 일까지 괜찮다는 건 아니에요."},new string[]{"기록이 남았으면 다음 배달은 몰래 하지 않아도 될까요."}),
            new AncientCitizen(7,1,207f,0f,"배급 담당 미루",3,new string[]{"남은 배급은 선착순이래요. 그런데 줄 순서도 포인트로 바뀌어요.","누군가 조커 표식을 남기고 배급함 잠금만 열었대요. 누가 했는지는 아무도 못 봤어요."},new string[]{"명단을 지우라는 요청이 왔어요. 대신 빈 종이를 제출했습니다."}),
            new AncientCitizen(8,1,229f,0f,"주민 은호",0,new string[]{"상층에서 왔다고 모두 여유로운 건 아니더군요. 포인트가 멈추면 내려올 길만 남아요.","제 이웃도 하루아침에 심사 보류가 됐어요. 이유는 비공개였고요."},new string[]{"심사 중이라는 말은 끝나는 날이 없어요. 기다리는 사람에게만 시간이 흐릅니다."}),
            new AncientCitizen(9,1,242f,0f,"식당 주인 보람",1,new string[]{"언니 연희는 아래 급식소를 맡아요. 전 여기서 야간 작업반 도시락을 만들고요.","포인트를 받으러 간 사람보다 기다리는 사람 이야기가 덜 남죠."},new string[]{"승진했어도 아래 가게는 들러요. 이름 대신 직급으로만 부르는 곳에 오래 있으면 힘들어요."}),
            new AncientCitizen(10,2,310f,0f,"기록원 다인",3,new string[]{"신고서의 빈칸은 주민이 채우지만 삭제 표시는 위에서 내려와요.","백 경위님, 제출 버튼을 누르기 전에 사본부터 만드세요."},new string[]{"누락 기록을 한 사건으로 묶었어요. 처음으로 신고한 사람들이 같은 줄에 들어왔네요."}),
            new AncientCitizen(11,2,332f,0f,"시설 관리원 규식",0,new string[]{"여기 셔터는 사람을 가두려는 게 아니라 기록을 지키려는 거래요.","그런데 기록이 지워질 때는 안쪽 사람도 못 나가죠."},new string[]{"폐기 장치가 멈춰서 종이 먼지 소리가 들립니다. 이 건물에 원래 있던 소리예요."}),
            new AncientCitizen(12,2,356f,0f,"민원인 하람",2,new string[]{"심사 한 번이면 올라갈 수 있다더니 심사받을 자격부터 다시 심사하네요.","저번 담당자는 조회권이 막혀 답을 못한대요. 높은 곳에 산다고 모든 문이 열리는 건 아니었어요."},new string[]{"이번엔 접수됐다는 문자를 받았어요. 답은 아직이어도 지워지진 않았네요."}),
            new AncientCitizen(13,2,369f,0f,"관제 수습 태린",1,new string[]{"조커는 사람 이름이 아니라 미분류 호출명이라고 배웠어요.","그 항목을 조회하자마자 교육 자료가 교체됐습니다. 제가 잘못 기억하는 걸까요."},new string[]{"교육 자료의 이전 버전을 보관했어요. 모르는 걸 모른다고 적는 것도 기록이죠."}),
            new AncientCitizen(14,2,391f,0f,"접수 직원 주안",3,new string[]{"조사관 칸과 피조사자 칸이 같은 양식에 있어요. 옮기는 건 클릭 한 번이고요.","경위님 이름이 어느 칸에 있든, 제가 본 건 바뀌지 않습니다."},new string[]{"안전 통로에 도착했어요. 사본도 가져왔습니다. 제 진술은 삭제하지 말아 주세요."}),
            new AncientCitizen(15,3,470f,0f,"설비사 지완",0,new string[]{"이 거리의 조명은 하층 배정과 별개래요. 같은 선을 쓰는데도요.","등 하나 끄는 권한보다 코어 하나의 행방을 묻는 권한이 더 높습니다."},new string[]{"분기 계측기를 주민도 볼 수 있게 열었어요. 더는 밝다는 이유로 괜찮다고 하진 못하겠죠."}),
            new AncientCitizen(16,3,495f,0f,"계약 담당 은재",3,new string[]{"서명만 받으면 된대요. 서명할 사람이 이미 이송됐어도요.","법무 검토에는 사람 이름 대신 세대 번호만 들어갑니다."},new string[]{"명단을 첨부에서 본문으로 옮겼어요. 적어도 계약서 첫 장에서 사람을 볼 수 있게요."}),
            new AncientCitizen(17,3,520f,0f,"정원 관리인 로운",1,new string[]{"여기 나무는 햇빛 없이도 자라요. 아래에서 올리는 영양분 덕분이죠.","보이지 않는다고 없는 건 아니에요. 이 거리도 혼자 서 있는 게 아닙니다."},new string[]{"급수 배관을 끊으라는 지시는 따르지 않았어요. 정원보다 아래 주민 쪽 밸브부터 봤죠."}),
            new AncientCitizen(18,3,536f,0f,"이송 예정자 해솔",2,new string[]{"안전한 곳으로 옮겨 준댔어요. 그런데 가족별 목적지가 다릅니다.","포인트가 사람마다 다르니까요. 같은 집에서 살았는데 말이죠."},new string[]{"함께 나왔어요. 어디서 살게 될지 몰라도 오늘은 함께 있습니다."}),
            new AncientCitizen(19,3,560f,0f,"경비 통신원 수현",3,new string[]{"발신지 없는 신호가 경비망을 스쳐요. 호출명은 조커라는데 응답하지 말래요.","위험 인물이라면서 뭘 했는지는 알려 주지 않네요."},new string[]{"제 명령서도 빈칸이더군요. 오늘은 빈칸을 근거로 사람을 쏘지 않겠습니다."}),
            new AncientCitizen(20,4,630f,0f,"정비 노동자 노을",0,new string[]{"여기선 발소리를 줄여요. 정비 노동자는 장비로 등록돼서 사람이 다니면 경보가 나죠.","명단에 없으면 없는 사람이 되는 곳입니다."},new string[]{"방금 총성은 기록에 없어요. 여긴 없는 소리가 너무 많네요."}),
            new AncientCitizen(21,4,654f,0f,"야간 관제원 여울",3,new string[]{"삭제 대기열이 쌓이는 밤에는 새 신청서를 받지 말래요. 지우는 일도 밀리면 곤란하니까요.","이의 신청이 들어온 흔적만이라도 남겨 주세요."},new string[]{"접수 시각은 보관했어요. 누가 신청했는지는 제 입으로 말하지 않겠습니다."}),
            new AncientCitizen(22,4,680f,0f,"청소 노동자 단아",1,new string[]{"회장실은 비어 있는데 정리하지 말래요. 책상에 노트 한 권이 남았습니다.","치우는 사람에게도 건드리지 말라는 물건이 있죠."},new string[]{"바닥의 먼지 자국이 화물 승강로로 이어집니다. 오늘은 짐이 많이 나갔어요."}),
            new AncientCitizen(23,4,706f,0f,"폐쇄망 정비사 도하",0,new string[]{"조커라는 호출명은 지워지지 않아요. 주인이 없다는 이유로 삭제 승인도 못 받거든요.","포인트가 멈춘 사람이 여기에 들어오면 누구나 이름 없는 호출명이 됩니다."},new string[]{"관제 화면이 꺼졌다고 사람이 사라진 건 아니에요. 신호 바깥에도 길이 있습니다."}),
            new AncientCitizen(24,4,738f,0f,"보관실 관리인 유담",2,new string[]{"집무실에 사람이 없다고 작전이 없는 건 아니에요. 실행 명령은 이미 내려갔습니다.","노트와 계획은 따로 보세요. 옛것을 찾는 이유는 오늘의 명령에 적혀 있으니까요."},new string[]{"창밖의 트럭이 움직였어요. 회수품만 실린 게 아닙니다."})
        };
        public static readonly string[] Reactions={"교대 서명은 제가 했어요. 제 이름을 지우지 말고 제가 본 시간도 같이 적어 주세요.","불이 켜지니까 안쪽에서 대답이 들려요. 문 너머에도 아직 사람이 있었군요.","다 나갔다고 써 있으면 제 목소리는 어디로 가는 거죠. 이제 밖에서 말할게요.","규정은 원본을 보내라지만 사본까지 버리라는 규정은 없어. 네가 지킨 것도 기록하겠다.","모니터가 다시 켜졌어요. 환자 이름부터 확인할게요. 코어 번호는 그다음이에요.","그분의 신청서는 제가 배달했어요. 거절 도장도 직접 봤고요. 그 사실만은 남겨 주세요.","배급함 자물쇠만 없애선 배급이 늘지 않더군요. 빈 상자가 더 또렷해졌어요.","장부가 남으면 제 서명도 남겠죠. 없는 물량을 받았다고 쓰라는 지시는 거부하겠습니다.","같은 사건이라고 써 줬군요. 저 사람들 신고서가 처음으로 같은 서류철에 들어갔어요.","스위치를 끄는 게 제 일이었는데, 오늘은 끄지 않은 덕분에 기록이 살아남았네요.","사본을 만든 날짜와 원본 수정 날짜가 증거가 됐다. 이제 누락이라고만 부를 수 없겠군.","밖에 나가서도 진술할게요. 제 이름이 어느 칸으로 옮겨져도 제가 본 건 같으니까요.","주민들이 계측기를 보게 할게요. 이 거리가 밝다는 이유로 질문을 멈추진 않겠습니다.","명단을 계약서 첫 장으로 옮겼어요. 서명하기 전에 사람 이름부터 보게 하려고요.","가족과 같은 통로로 나왔어요. 포인트가 달라도 오늘은 함께 걸을 수 있었네요.","점수는 승인됐는데 사람은 통과시키지 않겠다는 답이군. 네 판단까지 대신 승인받을 순 없다.","작업자용 통로가 열렸어요. 관제에는 장비 점검 완료라고만 남을 테지만요.","접수 시각은 제가 보관할게요. 없는 신청이었다고 말할 수 없도록요.","상대의 목적은 아직 몰라. 사격 흔적이 있다는 것과 누가 쐈는지는 다른 기록으로 남기자.","노트는 책상에 그대로 있어요. 계획의 날짜는 오늘입니다. 아직 창밖을 볼 시간이 있어요."};
        public static readonly string[][] Details={
            new string[]{"작업반 교대는 자정이지만 예비 코어 계량기는 새벽 두 시에도 움직였다.","일반 배정 계량기와 예비분 계량기의 봉인 번호가 다르다.","출고 전표에 목적지 대신 C-00 승인선만 찍혀 있다."},
            new string[]{"파손된 판 아래에서 주민용 비상 회로가 발견됐다.","봉인 명령은 현지 정비반 권한보다 높다.","전력 복구가 관제의 사용 승인보다 먼저 기록됐다."},
